candidate_proof:
cases t with
| empty => {
  simp [insert, toList]
  <;>
  (try
    {
      use [] []
      <;> simp_all [List.cons_append, List.append_cons, List.append_nil]
    })
  <;>
  (try
    {
      use (toList (insert cmp t v)) []
      <;> simp_all
    })
}
| node c l x r => {
  simp [insert, toList, Balanced] at *
  <;>
  (try
    {
      have h : cmp v x = LT ∨ cmp v x = GT ∨ cmp v x = EQ := by
        revert cmp v x
        decide
      rcases h with (h | h | h)
      · -- LT case
        {
          sorry
        }
      · -- GT case
        {
          sorry
        }
      · -- EQ case
        {
          sorry
        }
    })
}

